n = int(input())
a = sorted(map(int, input().split()))
res = []
for i in range(n - 2):
    if i and a[i] == a[i - 1]:
        continue
    if a[i] > 0:
        break
    l, r = i + 1, n - 1
    while l < r:
        s = a[i] + a[l] + a[r]
        if s < 0:
            l += 1
        elif s > 0:
            r -= 1
        else:
            res.append((a[i], a[l], a[r]))
            l += 1
            while l < r and a[l] == a[l - 1]:
                l += 1
            r -= 1
if res:
    print('\n'.join(f'{x} {y} {z}' for x, y, z in res))
else:
    print('NONE')

