n, t = map(int, input().split())
a = sorted(map(int, input().split()))
cnt = 0
for i in range(n - 3):
    if i and a[i] == a[i - 1]:
        continue
    for j in range(i + 1, n - 2):
        if j > i + 1 and a[j] == a[j - 1]:
            continue
        l, r = j + 1, n - 1
        need = t - a[i] - a[j]
        while l < r:
            s = a[l] + a[r]
            if s < need:
                l += 1
            elif s > need:
                r -= 1
            else:
                cnt += 1
                l += 1
                while l < r and a[l] == a[l - 1]:
                    l += 1
                r -= 1
print(cnt)
